-- =====================================================================
-- 0006_reports.sql
-- =====================================================================

-- 0006 Dashboard numbers and the data behind every export file. Run after 0005.
-- All of these run with the caller's rights (security invoker), so Row Level Security
-- decides which leads are counted: sales get their own, executives their projects.

-- Short code that stands for a customer in files sent to Claude (no name, no phone).
create function public.lead_code(p_id uuid) returns text
language sql immutable set search_path = '' as $$
  select 'C-' || upper(left(replace(p_id::text, '-', ''), 6))
$$;

-- Per sales person: workload and results for leads created in the range.
create function public.team_summary(p_project uuid default null, p_from date default null, p_to date default null)
returns table (
  owner_id uuid, owner_name text, leads_open bigint, leads_in_range bigint, activities bigint,
  activities_per_week numeric, avg_hours_to_first_contact numeric, overdue bigint,
  appointments bigint, visits bigint, reservations bigint, lost bigint, top_lost_reason text
)
language sql stable security invoker set search_path = '' as $$
  with rng as (
    select coalesce(p_from, public.today_th() - 29) as d1, coalesce(p_to, public.today_th()) as d2
  ),
  l as (
    select x.* from public.leads x, rng
    where x.owner_id is not null and (p_project is null or x.project_id = p_project)
  ),
  inr as (select l.* from l, rng where (l.created_at at time zone 'Asia/Bangkok')::date between rng.d1 and rng.d2),
  reached as (
    select h.lead_id, h.to_stage from public.stage_history h join inr on inr.id = h.lead_id group by 1, 2
  )
  select
    p.id,
    p.full_name,
    (select count(*) from l where l.owner_id = p.id and public.is_open_stage(l.stage)),
    (select count(*) from inr where inr.owner_id = p.id),
    (select count(*) from public.activities a join l on l.id = a.lead_id, rng
      where a.created_by = p.id and (a.created_at at time zone 'Asia/Bangkok')::date between rng.d1 and rng.d2),
    round((select count(*) from public.activities a join l on l.id = a.lead_id, rng
      where a.created_by = p.id and (a.created_at at time zone 'Asia/Bangkok')::date between rng.d1 and rng.d2)::numeric
      / greatest(((select d2 - d1 + 1 from rng))::numeric / 7, 1), 1),
    round((select avg(extract(epoch from inr.first_contact_at - inr.created_at) / 3600)
      from inr where inr.owner_id = p.id and inr.first_contact_at is not null)::numeric, 1),
    (select count(*) from l where l.owner_id = p.id and public.is_open_stage(l.stage) and l.next_follow_up < public.today_th()),
    (select count(*) from reached r join inr on inr.id = r.lead_id where inr.owner_id = p.id and r.to_stage = 'appointment'),
    (select count(*) from inr where inr.owner_id = p.id and inr.visited_at is not null),
    (select count(*) from reached r join inr on inr.id = r.lead_id where inr.owner_id = p.id and r.to_stage = 'reserved'),
    (select count(*) from inr where inr.owner_id = p.id and inr.stage = 'lost'),
    (select lr.label from inr join public.lost_reasons lr on lr.id = inr.lost_reason_id
      where inr.owner_id = p.id group by lr.label order by count(*) desc limit 1)
  from public.profiles p
  where p.role = 'sales' and (exists (select 1 from l where l.owner_id = p.id) or p.status = 'active')
  order by p.full_name
$$;

-- Everything on the executive dashboard in one call.
create function public.dashboard(p_project uuid default null, p_from date default null, p_to date default null)
returns jsonb
language sql stable security invoker set search_path = '' as $$
  with rng as (
    select coalesce(p_from, public.today_th() - 29) as d1, coalesce(p_to, public.today_th()) as d2
  ),
  l as (
    select x.* from public.leads x where (p_project is null or x.project_id = p_project)
  ),
  inr as (select l.* from l, rng where (l.created_at at time zone 'Asia/Bangkok')::date between rng.d1 and rng.d2),
  moves as (
    select h.*, l.project_id, l.campaign_id from public.stage_history h join l on l.id = h.lead_id, rng
    where (h.changed_at at time zone 'Asia/Bangkok')::date between rng.d1 and rng.d2
  ),
  reached as (
    select h.lead_id, h.to_stage from public.stage_history h join inr on inr.id = h.lead_id group by 1, 2
  ),
  stages as (
    select s, ord from unnest(array['new','qualified','appointment','visited','reserved','contracted','transferred']::public.lead_stage[])
      with ordinality as t(s, ord)
  )
  select jsonb_build_object(
    'from', (select d1 from rng),
    'to', (select d2 from rng),
    'kpi', jsonb_build_object(
      'new_leads', (select count(*) from inr),
      'appointments', (select count(*) from moves where to_stage = 'appointment'),
      'reservations', (select count(*) from moves where to_stage = 'reserved'),
      'transfers', (select count(*) from moves where to_stage = 'transferred'),
      'overdue', (select count(*) from l where public.is_open_stage(stage) and next_follow_up < public.today_th())
    ),
    -- leads created in the range that reached each stage (at any time)
    'funnel', (select jsonb_agg(jsonb_build_object(
        'stage', s,
        'count', (select count(distinct r.lead_id) from reached r
                   where array_position(enum_range(null::public.lead_stage), r.to_stage)
                         >= array_position(enum_range(null::public.lead_stage), stages.s)
                     and r.to_stage not in ('lost', 'unqualified'))
      ) order by ord) from stages),
    'current', (select coalesce(jsonb_object_agg(stage, n), '{}') from (select stage, count(*) n from l group by stage) c),
    'by_project', (select coalesce(jsonb_agg(row_to_json(x) order by x.name), '[]') from (
        select pr.id, pr.name,
          (select count(*) from inr where inr.project_id = pr.id) as leads,
          (select count(*) from moves m where m.project_id = pr.id and m.to_stage = 'appointment') as appointments,
          (select count(*) from moves m where m.project_id = pr.id and m.to_stage = 'reserved') as reservations,
          (select count(*) from moves m where m.project_id = pr.id and m.to_stage = 'transferred') as transfers,
          (select coalesce(sum(u.price), 0) from public.units u where u.project_id = pr.id
             and u.status in ('reserved', 'contracted', 'transferred')) as sold_value,
          (select count(*) from public.units u where u.project_id = pr.id and u.status in ('available', 'interested')) as units_left,
          (select coalesce(sum(u.price), 0) from public.units u where u.project_id = pr.id
             and u.status in ('available', 'interested')) as value_left
        from public.projects pr where p_project is null or pr.id = p_project) x),
    'by_campaign', (select coalesce(jsonb_agg(row_to_json(x) order by x.leads desc), '[]') from (
        select coalesce(c.name, 'ไม่ระบุแคมเปญ') as name,
          count(*) as leads,
          count(*) filter (where exists (select 1 from reached r where r.lead_id = inr.id and r.to_stage = 'qualified')) as qualified,
          count(*) filter (where inr.visited_at is not null) as visited,
          count(*) filter (where exists (select 1 from reached r where r.lead_id = inr.id and r.to_stage = 'reserved')) as reserved
        from inr left join public.campaigns c on c.id = inr.campaign_id
        group by c.name) x),
    'lost_reasons', (select coalesce(jsonb_agg(row_to_json(x) order by x.count desc), '[]') from (
        select lr.label, count(*) as count from inr join public.lost_reasons lr on lr.id = inr.lost_reason_id
        group by lr.label) x),
    'by_sales', (select coalesce(jsonb_agg(row_to_json(t)), '[]') from public.team_summary(p_project, p_from, p_to) t)
  )
$$;

-- ---------------------------------------------------------------
-- Export files (the server turns these rows into CSV files Excel reads in Thai)
-- ---------------------------------------------------------------
create function public.export_leads(
  p_project uuid default null, p_owner uuid default null, p_stage public.lead_stage default null,
  p_from date default null, p_to date default null
)
returns table (
  full_name text, phone text, email text, project text, owner text, campaign text, stage public.lead_stage,
  visited boolean, visited_at timestamptz, next_follow_up date, last_note text, created_at timestamptz
)
language sql stable security invoker set search_path = '' as $$
  select l.full_name, l.phone, l.email, pr.name, p.full_name, c.name, l.stage,
    l.visited_at is not null, l.visited_at, l.next_follow_up, l.last_note, l.created_at
  from public.leads l
  join public.projects pr on pr.id = l.project_id
  left join public.profiles p on p.id = l.owner_id
  left join public.campaigns c on c.id = l.campaign_id
  where (p_project is null or l.project_id = p_project)
    and (p_owner is null or l.owner_id = p_owner)
    and (p_stage is null or l.stage = p_stage)
    and (p_from is null or (l.created_at at time zone 'Asia/Bangkok')::date >= p_from)
    and (p_to is null or (l.created_at at time zone 'Asia/Bangkok')::date <= p_to)
  order by l.created_at desc
$$;

create function public.export_activities(
  p_project uuid default null, p_owner uuid default null, p_from date default null, p_to date default null
)
returns table (customer text, project text, type public.activity_type, note text, created_at timestamptz, by_name text)
language sql stable security invoker set search_path = '' as $$
  select l.full_name, pr.name, a.type, a.note, a.created_at, p.full_name
  from public.activities a
  join public.leads l on l.id = a.lead_id
  join public.projects pr on pr.id = l.project_id
  left join public.profiles p on p.id = a.created_by
  where (p_project is null or l.project_id = p_project)
    and (p_owner is null or a.created_by = p_owner)
    and (p_from is null or (a.created_at at time zone 'Asia/Bangkok')::date >= p_from)
    and (p_to is null or (a.created_at at time zone 'Asia/Bangkok')::date <= p_to)
  order by a.created_at desc
$$;

-- Follow-ups due today or overdue, grouped by sales person.
create function public.export_overdue(p_project uuid default null, p_owner uuid default null)
returns table (owner text, customer text, phone text, project text, stage public.lead_stage,
               next_follow_up date, days_overdue int, last_note text)
language sql stable security invoker set search_path = '' as $$
  select coalesce(p.full_name, 'ยังไม่มีเจ้าของ'), l.full_name, l.phone, pr.name, l.stage, l.next_follow_up,
    public.today_th() - l.next_follow_up, l.last_note
  from public.leads l
  join public.projects pr on pr.id = l.project_id
  left join public.profiles p on p.id = l.owner_id
  where public.is_open_stage(l.stage) and l.next_follow_up <= public.today_th()
    and (p_project is null or l.project_id = p_project)
    and (p_owner is null or l.owner_id = p_owner)
  order by 1, l.next_follow_up
$$;

-- Audience list for Meta: phone (international format) and email only.
-- p_group: unqualified · lost · visited · reserved (reserved, contracted, transferred) · all
create function public.export_meta_audience(p_group text, p_project uuid default null)
returns table (phone text, email text)
language plpgsql stable security invoker set search_path = '' as $$
begin
  if public.my_role() not in ('admin', 'executive') then raise exception 'not allowed'; end if;
  return query
    select distinct
      case when l.phone ~ '^0[0-9]{8,9}$' then '66' || substr(l.phone, 2) else l.phone end,
      l.email
    from public.leads l
    where (p_project is null or l.project_id = p_project)
      and case p_group
        when 'unqualified' then l.stage = 'unqualified'
        when 'lost' then l.stage = 'lost'
        when 'visited' then l.visited_at is not null
        when 'reserved' then l.stage in ('reserved', 'contracted', 'transferred')
        when 'all' then true
        else false
      end;
end
$$;

-- Sales-team analysis pack for Claude: activities with notes, customers shown as codes.
create function public.team_pack_activities(p_project uuid default null, p_from date default null, p_to date default null)
returns table (customer_code text, project text, sales text, type public.activity_type, note text,
               created_at timestamptz, stage_now public.lead_stage, lead_created_at timestamptz)
language plpgsql stable security invoker set search_path = '' as $$
begin
  if public.my_role() not in ('admin', 'executive') then raise exception 'not allowed'; end if;
  return query
    select public.lead_code(l.id), pr.name, p.full_name, a.type,
      -- notes can contain phone numbers; mask anything that looks like one
      regexp_replace(a.note, '0[0-9][0-9 -]{7,11}[0-9]', '[เบอร์โทร]', 'g'),
      a.created_at, l.stage, l.created_at
    from public.activities a
    join public.leads l on l.id = a.lead_id
    join public.projects pr on pr.id = l.project_id
    left join public.profiles p on p.id = a.created_by
    where (p_project is null or l.project_id = p_project)
      and (a.created_at at time zone 'Asia/Bangkok')::date between coalesce(p_from, public.today_th() - 29) and coalesce(p_to, public.today_th())
    order by p.full_name, a.created_at;
end
$$;

-- "My results this month" on /me: this month next to last month (Bangkok months).
create function public.my_month_stats()
returns table (metric text, this_month bigint, last_month bigint)
language sql stable security invoker set search_path = '' as $$
  with m as (
    select date_trunc('month', public.today_th())::date as m0,
           (date_trunc('month', public.today_th()) - interval '1 month')::date as m1
  ),
  b as (
    select 'new_leads' as metric, (l.created_at at time zone 'Asia/Bangkok')::date as d
      from public.leads l where l.owner_id = auth.uid()
    union all
    select 'activities', (a.created_at at time zone 'Asia/Bangkok')::date
      from public.activities a where a.created_by = auth.uid()
    union all
    select case h.to_stage when 'appointment' then 'appointments' else 'reservations' end,
           (h.changed_at at time zone 'Asia/Bangkok')::date
      from public.stage_history h join public.leads l on l.id = h.lead_id
      where l.owner_id = auth.uid() and h.to_stage in ('appointment', 'reserved')
  )
  select k.metric,
    (select count(*) from b, m where b.metric = k.metric and b.d >= m.m0),
    (select count(*) from b, m where b.metric = k.metric and b.d >= m.m1 and b.d < m.m0)
  from unnest(array['new_leads', 'activities', 'appointments', 'reservations']) with ordinality as k(metric, ord)
  order by k.ord
$$;

grant execute on function
  public.lead_code(uuid), public.my_month_stats(),
  public.team_summary(uuid, date, date), public.dashboard(uuid, date, date),
  public.export_leads(uuid, uuid, public.lead_stage, date, date),
  public.export_activities(uuid, uuid, date, date),
  public.export_overdue(uuid, uuid),
  public.export_meta_audience(text, uuid),
  public.team_pack_activities(uuid, date, date)
to authenticated;

revoke execute on all functions in schema public from public, anon;
grant execute on function public.invite_info(uuid) to anon, authenticated;

-- The server (secret key = service_role) runs the cron jobs, Meta sending and push.
-- Give it every table and function explicitly, whatever the project's default privileges are.
grant usage on schema public to service_role;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;

-- =====================================================================
-- 0007_project_images.sql
-- =====================================================================

-- 0007 Project cover picture and plot counts per project. Run after 0006.

-- Cover picture of a project: a file in the "project-images" storage bucket,
-- stored as <project_id>/cover-<timestamp>.jpg
alter table public.projects add column cover_path text;

-- Plot counts of every project the caller can see, in one call (the /projects cards).
-- Runs with the caller's rights, so Row Level Security on units decides what is counted.
create function public.project_unit_counts()
returns table (
  project_id uuid, total int, available int, interested int, reserved int, contracted int, transferred int,
  free_value numeric
)
language sql stable security invoker set search_path = '' as $$
  select
    u.project_id,
    count(*)::int,
    count(*) filter (where u.status = 'available')::int,
    count(*) filter (where u.status = 'interested')::int,
    count(*) filter (where u.status = 'reserved')::int,
    count(*) filter (where u.status = 'contracted')::int,
    count(*) filter (where u.status = 'transferred')::int,
    coalesce(sum(u.price) filter (where u.status in ('available', 'interested')), 0)
  from public.units u
  group by u.project_id
$$;

-- Private bucket: everyone who can see the project can view its pictures; only admins add or remove them.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('project-images', 'project-images', false, 5242880, array['image/jpeg', 'image/webp', 'image/png'])
on conflict (id) do nothing;

create policy project_images_files_select on storage.objects for select to authenticated
  using (bucket_id = 'project-images' and public.can_see_project(((storage.foldername(name))[1])::uuid));
create policy project_images_files_admin on storage.objects for all to authenticated
  using (bucket_id = 'project-images' and public.is_admin())
  with check (bucket_id = 'project-images' and public.is_admin());

revoke execute on function public.project_unit_counts() from public, anon;
grant execute on function public.project_unit_counts() to authenticated, service_role;

-- =====================================================================
-- 0008_import_keeps_reserved.sql
-- =====================================================================

-- 0008 Re-importing the plot list never changes the status of a plot a customer holds.
-- Run after 0007.

create or replace function public.import_units(p_project uuid, p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r jsonb;
  i int := 0;
  v_ins int := 0;
  v_upd int := 0;
  v_err jsonb := '[]';
  v_code text;
  v_status public.unit_status;
  v_inserted boolean;
begin
  if not public.is_admin() then raise exception 'admin only'; end if;
  if not exists (select 1 from public.projects where id = p_project) then raise exception 'project not found'; end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    i := i + 1;
    v_code := upper(trim(coalesce(r ->> 'code', '')));
    begin
      if v_code = '' then raise exception 'ไม่มีเลขแปลง'; end if;
      v_status := public.unit_status_from_text(r ->> 'status');
      if v_status is null then raise exception 'สถานะไม่ถูกต้อง: %', r ->> 'status'; end if;

      insert into public.units as u (project_id, code, zone, house_type, land_sqw, usable_sqm, price, status, note, updated_by)
      values (
        p_project, v_code,
        trim(coalesce(r ->> 'zone', '')),
        trim(coalesce(r ->> 'house_type', '')),
        nullif(regexp_replace(coalesce(r ->> 'land_sqw', ''), '[^0-9.]', '', 'g'), '')::numeric,
        nullif(regexp_replace(coalesce(r ->> 'usable_sqm', ''), '[^0-9.]', '', 'g'), '')::numeric,
        nullif(regexp_replace(coalesce(r ->> 'price', ''), '[^0-9.]', '', 'g'), '')::numeric,
        v_status,
        trim(coalesce(r ->> 'note', '')),
        auth.uid()
      )
      on conflict (project_id, code) do update set
        zone = excluded.zone,
        house_type = excluded.house_type,
        land_sqw = excluded.land_sqw,
        usable_sqm = excluded.usable_sqm,
        price = excluded.price,
        -- a plot held by a customer keeps its status; change it on the plot page instead
        status = case when u.lead_id is not null or coalesce(trim(r ->> 'status'), '') = '' then u.status else excluded.status end,
        note = excluded.note,
        updated_by = auth.uid(),
        updated_at = now()
      returning (xmax = 0) into v_inserted;
      if v_inserted then v_ins := v_ins + 1; else v_upd := v_upd + 1; end if;
    exception when others then
      v_err := v_err || jsonb_build_object('row', i + 1, 'code', v_code, 'error', sqlerrm);
    end;
  end loop;

  return jsonb_build_object('inserted', v_ins, 'updated', v_upd, 'errors', v_err);
end
$$;

-- =====================================================================
-- 0009_today_for_managers.sql
-- =====================================================================

-- 0009 "My work today" for managers: admin and executives can look at the whole team's
-- follow-ups, or one sales person's. Sales still see only their own (Row Level Security).
-- Run after 0008.

drop function if exists public.today_list();

-- p_owner: null = the signed-in user · a user id = that person's leads
-- p_all: true = every lead the caller may see (whole team)
create function public.today_list(p_owner uuid default null, p_all boolean default false)
returns table (
  bucket text, lead_id uuid, full_name text, phone text, project_name text, stage public.lead_stage,
  last_note text, next_follow_up date, days_overdue int, appointment_at timestamptz,
  owner_id uuid, owner_name text
)
language sql stable security invoker set search_path = '' as $$
  select * from (
    select
      case
        when l.next_follow_up < public.today_th() then 'overdue'
        when l.first_contact_at is null then 'new'
        when l.next_follow_up = public.today_th() then 'today'
        when l.next_follow_up <= public.today_th() + 7 then 'week'
      end as bucket,
      l.id as lead_id, l.full_name as lead_name, l.phone, pr.name as project_name, l.stage, l.last_note,
      l.next_follow_up as follow_up, greatest(public.today_th() - l.next_follow_up, 0) as days_overdue,
      l.appointment_at, l.owner_id, p.full_name as owner_name
    from public.leads l
    join public.projects pr on pr.id = l.project_id
    left join public.profiles p on p.id = l.owner_id
    where public.is_open_stage(l.stage)
      and case
            when p_all and public.my_role() in ('admin', 'executive') then true
            when p_owner is not null and public.my_role() in ('admin', 'executive') then l.owner_id = p_owner
            else l.owner_id = auth.uid()
          end
  ) x
  where bucket is not null
  order by array_position(array['overdue', 'new', 'today', 'week'], x.bucket), x.follow_up, x.lead_name
$$;

revoke execute on function public.today_list(uuid, boolean) from public, anon;
grant execute on function public.today_list(uuid, boolean) to authenticated, service_role;

-- ---------------------------------------------------------------
-- Profile pictures: Google sends one with every sign-in. Shown next to names everywhere.
-- ---------------------------------------------------------------
alter table public.profiles add column avatar_url text not null default '';

update public.profiles p set avatar_url = coalesce(u.raw_user_meta_data ->> 'avatar_url', u.raw_user_meta_data ->> 'picture', '')
from auth.users u where u.id = p.id;

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_role public.user_role := 'sales';
  v_status public.user_status := 'pending';
begin
  perform pg_advisory_xact_lock(727001); -- two people signing up at once cannot both become the first admin

  if not exists (select 1 from public.profiles) then
    v_role := 'admin';
    v_status := 'active';
  end if;

  insert into public.profiles (id, full_name, email, role, status, avatar_url)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name', ''),
    coalesce(new.email, ''),
    v_role,
    v_status,
    coalesce(new.raw_user_meta_data ->> 'avatar_url', new.raw_user_meta_data ->> 'picture', '')
  );
  return new;
end
$$;

-- Keep the picture current when Google sends a new one at sign-in.
create function public.sync_avatar() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.profiles
    set avatar_url = coalesce(new.raw_user_meta_data ->> 'avatar_url', new.raw_user_meta_data ->> 'picture', avatar_url)
    where id = new.id;
  return new;
end
$$;
create trigger on_auth_user_updated
  after update of raw_user_meta_data on auth.users
  for each row execute function public.sync_avatar();
revoke execute on function public.sync_avatar() from public, anon;

-- =====================================================================
-- 0010_house_models.sql
-- =====================================================================

-- 0010 House models of each project (แบบบ้าน), with a picture and a category. Run after 0009.
--
-- A plot (unit) points to its model. The Excel import still fills units.house_type as text;
-- a trigger links the plot to the model whose name appears in that text ("บ้านเดี่ยว แบบ Ivy" -> Ivy).

create type public.house_category as enum ('detached', 'semi_detached', 'townhome', 'shophouse');

create table public.house_models (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects on delete cascade,
  name text not null check (trim(name) <> ''), -- e.g. Ivy
  category public.house_category not null,
  bedrooms int check (bedrooms >= 0),
  bathrooms int check (bathrooms >= 0),
  parking int check (parking >= 0),
  usable_sqm numeric(10, 2),
  land_from_sqw numeric(10, 2),
  price_from numeric(14, 2),
  description text not null default '',
  -- file in the "project-images" bucket: <project_id>/models/<model_id>-<timestamp>.jpg
  image_path text,
  sort int not null default 0,
  created_at timestamptz not null default now(),
  unique (project_id, name)
);
create index house_models_project_idx on public.house_models (project_id, sort);

alter table public.units add column house_model_id uuid references public.house_models on delete set null;
create index units_house_model_idx on public.units (house_model_id);

-- ---------------------------------------------------------------
-- Matching a plot's house_type text to a model
-- ---------------------------------------------------------------

-- The model of this project whose name appears in the text (case-insensitive). Longest name wins,
-- so "Ivy Plus" beats "Ivy". Null when nothing matches.
create function public.house_model_for(p_project uuid, p_house_type text) returns uuid
language sql stable security definer set search_path = '' as $$
  select m.id
  from public.house_models m
  where m.project_id = p_project
    and trim(coalesce(p_house_type, '')) <> ''
    and strpos(lower(p_house_type), lower(trim(m.name))) > 0
  order by length(trim(m.name)) desc, m.name
  limit 1
$$;

-- Before a plot is saved: fill house_model_id from house_type when it is empty,
-- and refuse a model that belongs to another project. When an update (e.g. a new Excel import)
-- changes house_type but does not set the model itself, the model follows the new text.
create function public.units_link_house_model() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'UPDATE' and new.house_type is distinct from old.house_type
    and new.house_model_id is not distinct from old.house_model_id then
    new.house_model_id := public.house_model_for(new.project_id, new.house_type);
  elsif new.house_model_id is null and trim(coalesce(new.house_type, '')) <> '' then
    new.house_model_id := public.house_model_for(new.project_id, new.house_type);
  elsif new.house_model_id is not null
    and not exists (select 1 from public.house_models m where m.id = new.house_model_id and m.project_id = new.project_id) then
    raise exception 'house model of another project';
  end if;
  return new;
end
$$;
create trigger units_link_house_model before insert or update on public.units
  for each row execute function public.units_link_house_model();

-- A new or renamed model picks up the plots of its project that have no model yet.
create function public.house_models_backfill_units() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.units u
  set house_model_id = public.house_model_for(u.project_id, u.house_type)
  where u.project_id = new.project_id
    and u.house_model_id is null
    and trim(u.house_type) <> ''
    and strpos(lower(u.house_type), lower(trim(new.name))) > 0;
  return null;
end
$$;
create trigger house_models_backfill_units after insert or update of name on public.house_models
  for each row execute function public.house_models_backfill_units();

-- ---------------------------------------------------------------
-- unit_board(): same columns and order as 0004, plus the model at the end
-- ---------------------------------------------------------------
drop function public.unit_board(uuid);

create function public.unit_board(p_project uuid)
returns table (
  id uuid, code text, zone text, house_type text, land_sqw numeric, usable_sqm numeric, price numeric,
  status public.unit_status, note text, plan_id uuid, pos_x real, pos_y real,
  interest_count int, lead_id uuid, lead_name text, holder_name text, mine boolean, updated_at timestamptz,
  house_model_id uuid, model_name text, model_category public.house_category
)
language sql stable security definer set search_path = '' as $$
  select
    u.id, u.code, u.zone, u.house_type, u.land_sqw, u.usable_sqm, u.price, u.status, u.note,
    u.plan_id, u.pos_x, u.pos_y,
    (select count(*)::int from public.unit_interests i where i.unit_id = u.id),
    case when public.lead_visible(l.project_id, l.owner_id) then l.id end,
    case when public.lead_visible(l.project_id, l.owner_id) then l.full_name end,
    p.full_name,
    coalesce(l.owner_id = auth.uid(), false),
    u.updated_at,
    m.id, m.name, m.category
  from public.units u
  left join public.leads l on l.id = u.lead_id
  left join public.profiles p on p.id = l.owner_id
  left join public.house_models m on m.id = u.house_model_id
  where u.project_id = p_project and public.can_see_project(p_project)
  order by u.zone, u.code
$$;

-- ---------------------------------------------------------------
-- Row Level Security and access
-- ---------------------------------------------------------------
alter table public.house_models enable row level security;

create policy house_models_select on public.house_models for select to authenticated
  using (public.can_see_project(project_id));
create policy house_models_admin on public.house_models for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

grant select, insert, update, delete on public.house_models to authenticated;
grant all on public.house_models to service_role;

revoke execute on function
  public.house_model_for(uuid, text), public.units_link_house_model(), public.house_models_backfill_units(),
  public.unit_board(uuid)
from public, anon;
grant execute on function public.house_model_for(uuid, text), public.unit_board(uuid) to authenticated, service_role;

-- Pictures use the existing private "project-images" bucket (0007): the first folder is the
-- project id, so its policies already cover <project_id>/models/... files.

-- =====================================================================
-- 0011_lead_stage_counts.sql
-- =====================================================================

-- 0011 Counts for the stage tabs on /leads: how many leads per stage, plus how many are overdue,
-- with the same filters as search_leads (0003) except stage and overdue themselves.
-- Security invoker: Row Level Security limits sales to their own leads, like the list.
-- Run after 0010.

create function public.lead_stage_counts(
  p_q text default null,
  p_project uuid default null,
  p_owner uuid default null,
  p_campaign uuid default null,
  p_from date default null,
  p_to date default null
)
returns table (stage text, n bigint)
language sql stable security invoker set search_path = '' as $$
  with f as (
    select l.stage, l.next_follow_up
    from public.leads l
    where (p_q is null or p_q = ''
           or l.full_name ilike '%' || p_q || '%'
           or (length(public.normalize_phone(p_q)) >= 3 and l.phone like '%' || public.normalize_phone(p_q) || '%'))
      and (p_project is null or l.project_id = p_project)
      and (p_owner is null or l.owner_id = p_owner)
      and (p_campaign is null or l.campaign_id = p_campaign)
      and (p_from is null or (l.created_at at time zone 'Asia/Bangkok')::date >= p_from)
      and (p_to is null or (l.created_at at time zone 'Asia/Bangkok')::date <= p_to)
  )
  select f.stage::text, count(*) from f group by f.stage
  union all
  select 'overdue', count(*) from f where f.next_follow_up < public.today_th()
$$;

revoke execute on function public.lead_stage_counts(text, uuid, uuid, uuid, date, date) from public, anon;
grant execute on function public.lead_stage_counts(text, uuid, uuid, uuid, date, date) to authenticated, service_role;

-- =====================================================================
-- 0012_meta_standard_event_names.sql
-- =====================================================================

-- Default Meta event names are now Meta standard events, so every stage has a ready-made
-- column in Ads Manager (custom names like QualifiedLead need a custom conversion, and
-- custom conversions do not accept system_generated events). Admins can still rename per project.
create or replace function public.default_event_name(s public.lead_stage) returns text
language sql immutable set search_path = '' as $$
  select case s
    when 'new' then 'Lead'
    when 'qualified' then 'SubmitApplication'
    when 'appointment' then 'Schedule'
    when 'visited' then 'Contact'
    when 'reserved' then 'InitiateCheckout'
    when 'contracted' then 'AddPaymentInfo'
    when 'transferred' then 'Purchase'
  end
$$;

-- =====================================================================
-- 0013_meta_audience_names.sql
-- =====================================================================

-- Audience list for Meta now also returns the customer's name, so the file can carry
-- fn / ln / country (Meta matches more people with them). Same groups and rights as 0006.
drop function if exists public.export_meta_audience(text, uuid);
create function public.export_meta_audience(p_group text, p_project uuid default null)
returns table (phone text, email text, full_name text)
language plpgsql stable security invoker set search_path = '' as $$
begin
  if public.my_role() not in ('admin', 'executive') then raise exception 'not allowed'; end if;
  return query
    select distinct
      case when l.phone ~ '^0[0-9]{8,9}$' then '66' || substr(l.phone, 2) else l.phone end,
      l.email,
      l.full_name
    from public.leads l
    where (p_project is null or l.project_id = p_project)
      and case p_group
        when 'unqualified' then l.stage = 'unqualified'
        when 'lost' then l.stage = 'lost'
        when 'visited' then l.visited_at is not null
        when 'reserved' then l.stage in ('reserved', 'contracted', 'transferred')
        when 'all' then true
        else false
      end;
end
$$;
grant execute on function public.export_meta_audience(text, uuid) to authenticated;
